CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE loyalty_tiers(code text PRIMARY KEY CHECK(code IN ('MEMBER','DRIVE','BLACK','RED','SIGNATURE')), rank integer UNIQUE NOT NULL, name text NOT NULL);
INSERT INTO loyalty_tiers VALUES ('MEMBER',0,'MEMBER'),('DRIVE',1,'DRIVE'),('BLACK',2,'BLACK'),('RED',3,'RED'),('SIGNATURE',4,'SIGNATURE');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), phone text UNIQUE CHECK(phone ~ '^\+[1-9][0-9]{7,14}$'), telegram_id bigint UNIQUE, telegram_username text, crm_customer_id text, public_member_id text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(12),'hex'), referral_code text NOT NULL UNIQUE DEFAULT ('RPM-'||upper(encode(gen_random_bytes(6),'hex'))), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','blocked')), marketing_consent boolean NOT NULL DEFAULT false, telegram_reachable boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_external_identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL, crm_customer_id text NOT NULL, user_id uuid NOT NULL REFERENCES users, UNIQUE(source,crm_customer_id));
CREATE TABLE loyalty_accounts(user_id uuid PRIMARY KEY REFERENCES users, calculated_tier text NOT NULL DEFAULT 'MEMBER' REFERENCES loyalty_tiers, achieved_tier text NOT NULL DEFAULT 'MEMBER' REFERENCES loyalty_tiers, manual_override text REFERENCES loyalty_tiers, total_rental_amount bigint NOT NULL DEFAULT 0 CHECK(total_rental_amount>=0), bonus_available bigint NOT NULL DEFAULT 0 CHECK(bonus_available>=0), bonus_pending bigint NOT NULL DEFAULT 0 CHECK(bonus_pending>=0), bonus_debt bigint NOT NULL DEFAULT 0 CHECK(bonus_debt>=0), member_since timestamptz, account_version bigint NOT NULL DEFAULT 0, CHECK(bonus_available=0 OR bonus_debt=0));
CREATE FUNCTION create_loyalty_account() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO loyalty_accounts(user_id) VALUES(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER user_account AFTER INSERT ON users FOR EACH ROW EXECUTE FUNCTION create_loyalty_account();
CREATE TABLE program_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version integer NOT NULL UNIQUE, tiers jsonb NOT NULL, redemption_limit_bps integer NOT NULL CHECK(redemption_limit_bps BETWEEN 0 AND 10000), expiry_days integer NOT NULL CHECK(expiry_days BETWEEN 1 AND 36500), referrer_reward bigint NOT NULL CHECK(referrer_reward>=0), referred_reward bigint NOT NULL CHECK(referred_reward>=0), program_starts_at timestamptz NOT NULL, effective_at timestamptz NOT NULL DEFAULT now(), published_by text NOT NULL);
INSERT INTO program_versions(version,tiers,redemption_limit_bps,expiry_days,referrer_reward,referred_reward,program_starts_at,published_by) VALUES(1,'[{"code":"MEMBER","thresholdKopecks":"0","rateBps":200,"benefits":["RPM Drops","Реферальная программа","Цифровая карта"]},{"code":"DRIVE","thresholdKopecks":"10000000","rateBps":300,"benefits":["Ранний доступ к Drops","Приоритет обращения"]},{"code":"BLACK","thresholdKopecks":"30000000","rateBps":400,"benefits":["Приоритет бронирования","1 доставка в квартал"]},{"code":"RED","thresholdKopecks":"70000000","rateBps":500,"benefits":["2 доставки в квартал","Upgrade при наличии"]},{"code":"SIGNATURE","thresholdKopecks":"150000000","rateBps":700,"benefits":["Персональный менеджер","Максимальный приоритет","Special access"]}]',2000,365,3000,2000,'2026-01-01T00:00:00Z','system');
CREATE TABLE tier_benefits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tier_id text NOT NULL REFERENCES loyalty_tiers,title text NOT NULL,description text NOT NULL DEFAULT '',sort_order integer NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 1);
CREATE TABLE import_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),filename text NOT NULL,mode text NOT NULL CHECK(mode IN ('historical','operational')),profile jsonb NOT NULL DEFAULT '{}',program_version_id uuid REFERENCES program_versions,status text NOT NULL DEFAULT 'uploaded',cursor integer NOT NULL DEFAULT 0,lease_until timestamptz,file_path text,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rentals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),external_rental_id text NOT NULL UNIQUE CHECK(length(external_rental_id) BETWEEN 1 AND 128),user_id uuid NOT NULL REFERENCES users,source text NOT NULL,car_name text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,amount_kopecks bigint NOT NULL CHECK(amount_kopecks>0),current_amount_kopecks bigint NOT NULL CHECK(current_amount_kopecks>=0),status text NOT NULL CHECK(status IN ('completed','in_progress','cancelled')),payment_status text NOT NULL CHECK(payment_status IN ('paid','unpaid','partial','refunded')),qualified_at timestamptz NOT NULL,processed_at timestamptz,program_version_id uuid NOT NULL REFERENCES program_versions,applied_rate_bps integer NOT NULL DEFAULT 0,import_batch_id uuid REFERENCES import_batches,payload_hash text NOT NULL,mode text NOT NULL CHECK(mode IN ('historical','operational')),is_qualified boolean NOT NULL DEFAULT false,net_cashback bigint NOT NULL DEFAULT 0 CHECK(net_cashback>=0),cancelled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(start_date<=end_date));
CREATE TABLE import_rows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES import_batches,row_number integer NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',errors jsonb NOT NULL DEFAULT '[]',result jsonb,rental_id uuid REFERENCES rentals,UNIQUE(batch_id,row_number));
CREATE TABLE tier_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,from_tier text NOT NULL REFERENCES loyalty_tiers,to_tier text NOT NULL REFERENCES loyalty_tiers,reason text NOT NULL,rental_id uuid REFERENCES rentals,program_version_id uuid NOT NULL REFERENCES program_versions,actor_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rental_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rental_id uuid NOT NULL REFERENCES rentals,operation_key text NOT NULL UNIQUE,before_amount bigint NOT NULL,after_amount bigint NOT NULL,before_status text NOT NULL,after_status text NOT NULL,reason text NOT NULL,actor_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE redemption_references(external_rental_id text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,eligible_price_kopecks bigint NOT NULL CHECK(eligible_price_kopecks>0));
CREATE TABLE bonus_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,rental_id uuid REFERENCES rentals,external_rental_id text,type text NOT NULL CHECK(type IN ('rental_cashback','referral_reward','manual_credit','manual_debit','rental_payment','expiration','reversal')),amount bigint NOT NULL CHECK(amount<>0),posting_state text NOT NULL DEFAULT 'posted' CHECK(posting_state='posted'),business_key text NOT NULL UNIQUE,reverses_id uuid REFERENCES bonus_transactions,reason text NOT NULL,actor_id text NOT NULL,program_version_id uuid NOT NULL REFERENCES program_versions,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bonus_lots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,credit_transaction_id uuid NOT NULL UNIQUE REFERENCES bonus_transactions,issued_amount bigint NOT NULL CHECK(issued_amount>0),remaining_amount bigint NOT NULL CHECK(remaining_amount>=0 AND remaining_amount<=issued_amount),available_at timestamptz NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE bonus_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id uuid NOT NULL REFERENCES bonus_transactions,lot_id uuid NOT NULL REFERENCES bonus_lots,amount bigint NOT NULL CHECK(amount>0),kind text NOT NULL CHECK(kind IN ('spend','reversal','debt_offset','expiration','restore')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(transaction_id,lot_id,kind));
CREATE TABLE referrals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),referrer_id uuid NOT NULL REFERENCES users,referred_id uuid NOT NULL UNIQUE REFERENCES users,code_snapshot text NOT NULL,status text NOT NULL CHECK(status IN ('bound','qualified','rewarded','ineligible','reversed')),qualifying_rental_id uuid REFERENCES rentals,referrer_reward bigint,referred_reward bigint,program_version_id uuid REFERENCES program_versions,reason text,rewarded_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(referrer_id<>referred_id));
CREATE TABLE referral_rewards(referral_id uuid NOT NULL REFERENCES referrals,beneficiary_user_id uuid NOT NULL REFERENCES users,transaction_id uuid NOT NULL UNIQUE REFERENCES bonus_transactions,PRIMARY KEY(referral_id,beneficiary_user_id));
CREATE TABLE idempotency_requests(scope text NOT NULL,key text NOT NULL,payload_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,key));
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id text NOT NULL,actor_role text NOT NULL,action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,reason text NOT NULL,before_data jsonb,after_data jsonb,request_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_key text NOT NULL UNIQUE,event_type text NOT NULL,user_id uuid REFERENCES users,aggregate_id text NOT NULL,account_version bigint NOT NULL DEFAULT 0,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),expanded_at timestamptz);
CREATE TABLE deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES outbox_events,channel text NOT NULL CHECK(channel IN ('telegram','apple','google')),target text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','retry','succeeded','dead','suppressed')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token text,last_error text,delivered_version bigint,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,channel,target));
CREATE TABLE miniapp_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text NOT NULL UNIQUE,user_id uuid REFERENCES users,telegram_id bigint,telegram_profile jsonb NOT NULL DEFAULT '{}',expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contact_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES miniapp_sessions,telegram_id bigint NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz,phone text);
CREATE TABLE telegram_updates(update_id bigint PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_user_id uuid NOT NULL UNIQUE,email text NOT NULL,name text NOT NULL DEFAULT '',role text NOT NULL CHECK(role IN ('admin','manager','viewer')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE staff_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text NOT NULL UNIQUE,membership_id uuid NOT NULL REFERENCES admin_memberships,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE legal_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),type text NOT NULL CHECK(type IN ('rules','privacy','personal-data')),version text NOT NULL,title text NOT NULL,body text NOT NULL,published_at timestamptz NOT NULL DEFAULT now(),UNIQUE(type,version));
CREATE TABLE consent_acceptances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,document_id uuid NOT NULL REFERENCES legal_documents,accepted_at timestamptz NOT NULL DEFAULT now(),source text NOT NULL,UNIQUE(user_id,document_id));
CREATE TABLE marketing_consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,granted boolean NOT NULL,source text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,subtitle text,car_name text,image_url text,description text NOT NULL,old_price bigint CHECK(old_price>=0),new_price bigint CHECK(new_price>=0),minimum_tier text NOT NULL REFERENCES loyalty_tiers,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,cta_text text NOT NULL DEFAULT 'Подробнее',cta_url text NOT NULL,active boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(start_at<end_at),CHECK(new_price<=old_price));
CREATE TABLE offer_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),offer_id uuid NOT NULL REFERENCES offers,offer_version integer NOT NULL,audience jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'pending',requested_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(offer_id,offer_version));
CREATE TABLE wallet_passes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,platform text NOT NULL CHECK(platform IN ('apple','google')),serial_number text UNIQUE,pass_type_identifier text,google_object_id text UNIQUE,authentication_token_encrypted text,authentication_token_hash text,status text NOT NULL DEFAULT 'issued',account_version bigint NOT NULL DEFAULT 0,last_updated_at timestamptz NOT NULL DEFAULT now(),last_error text,save_clicked_at timestamptz,confirmed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,platform));
CREATE TABLE apple_devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_library_identifier text NOT NULL UNIQUE,push_token_encrypted text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE apple_registrations(device_id uuid NOT NULL REFERENCES apple_devices,pass_id uuid NOT NULL REFERENCES wallet_passes,registered_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(device_id,pass_id));
CREATE TABLE program_settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE analytics_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id text NOT NULL UNIQUE,user_id uuid REFERENCES users,name text NOT NULL,entity_id text,properties jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE operational_errors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL,entity_id text,details jsonb NOT NULL,resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits(key text PRIMARY KEY,count integer NOT NULL DEFAULT 0,window_start timestamptz NOT NULL DEFAULT now());
CREATE INDEX rentals_user_date ON rentals(user_id,qualified_at DESC,id);
CREATE INDEX bonus_history ON bonus_transactions(user_id,created_at DESC,id);
CREATE INDEX bonus_expiry ON bonus_lots(user_id,expires_at,id) WHERE remaining_amount>0;
CREATE INDEX deliveries_due ON deliveries(status,next_attempt_at);
CREATE INDEX offers_active ON offers(active,start_at,end_at);
CREATE INDEX audit_entity ON audit_logs(entity_type,entity_id,created_at DESC);
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only table %',TG_TABLE_NAME; END $$;
CREATE TRIGGER immutable_bonus BEFORE UPDATE OR DELETE ON bonus_transactions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_program BEFORE UPDATE OR DELETE ON program_versions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_adjustments BEFORE UPDATE OR DELETE ON rental_adjustments FOR EACH ROW EXECUTE FUNCTION immutable_record();
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t.tablename); END LOOP; IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon; END IF; IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON ALL TABLES IN SCHEMA public FROM authenticated; END IF; END $$;
